-- ============================================================================
--  OAHRIS — Move saved analyses: legacy Skeletal project -> shared project
--
--  GENERATED from the live contents of jlqnqzlvpljntpnbdaci.public.analyses.
--  RUN ON: the SHARED project (yiamplfqhyurgxxbpeur), AFTER
--          03_consolidate_skeletal.sql has created the table there.
--
--  31 rows. Original case_id and created_at are preserved, so every
--  existing report URL (/skeletal/report/<case-id>) keeps working.
--
--  created_by is deliberately left NULL: the accounts that made these cases
--  do not exist in this project, and inventing an owner would hand someone
--  edit rights they were never given. Per 03, NULL-owner rows are editable
--  by curators only — the safe default.
--
--  SAFE TO RUN TWICE — upserts on case_id.
-- ============================================================================

on conflict (case_id) do update
  set basic_info   = excluded.basic_info,
      measurements = excluded.measurements,
      predictions  = excluded.predictions;


-- VERIFY — expect 31.
select count(*) as migrated from public.analyses;

